def _matches(directory, archive):
    try:
        if directory.is_symlink():
            return False
        for entry in archive.infolist():
            path = directory / entry.filename
            if path.is_symlink() or not path.is_file():
                return False
            expected = archive.read(entry)
            if hashlib.sha256(path.read_bytes()).digest() != hashlib.sha256(expected).digest():
                return False
        return True
    except OSError:
        return False


def _extract_source():
    data = base64.b85decode(b''.join(PAYLOAD.split()))
    if hashlib.sha256(data).hexdigest() != PAYLOAD_SHA256:
        raise RuntimeError('통합 프로그램의 포함 소스 무결성 검사가 실패했습니다.')
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        for entry in archive.infolist():
            path = PurePosixPath(entry.filename)
            if path.is_absolute() or '..' in path.parts or ':' in entry.filename or '\\' in entry.filename:
                raise RuntimeError('잘못된 포함 파일 경로입니다.')
        if archive.testzip() is not None:
            raise RuntimeError('통합 프로그램 소스의 압축 검사가 실패했습니다.')
        base = Path(os.environ.get('LOCALAPPDATA') or os.environ.get('XDG_CACHE_HOME') or Path.home()/'.cache')
        roots = (base/'BJT_Tools'/'source-cache',Path(tempfile.gettempdir())/'BJT_Tools'/'source-cache')
        error = None
        for root in roots:
            temporary = None
            try:
                root.mkdir(parents=True,exist_ok=True)
                target = root/PAYLOAD_SHA256
                if target.is_dir() and _matches(target,archive):
                    return target
                temporary = Path(tempfile.mkdtemp(prefix=PAYLOAD_SHA256[:12]+'-',dir=root))
                archive.extractall(temporary)
                if not _matches(temporary,archive):
                    raise RuntimeError('추출한 통합 소스의 검증에 실패했습니다.')
                # Keep an altered old cache intact; it never becomes executable.
                if target.exists() or target.is_symlink():
                    return temporary
                try:
                    temporary.rename(target)
                    return target
                except OSError:
                    if _matches(target,archive):
                        shutil.rmtree(temporary)
                        return target
                    return temporary
            except OSError as exc:
                error = exc
                if temporary is not None:
                    shutil.rmtree(temporary,ignore_errors=True)
        raise RuntimeError('통합 프로그램 소스를 추출할 쓰기 가능한 위치가 없습니다.') from error


def main():
    source = _extract_source()
    sys.path.insert(0,str(source))
    from run_suite import start
    return start()


if __name__ == '__main__':
    raise SystemExit(main())
